package ru.assistant.infra;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class LogEventsTest {

    @Test
    public void safePreviewOfNullReturnsNullMarker() {
        assertEquals("<null>", LogEvents.safePreview(null));
    }

    @Test
    public void safePreviewDoesNotContainOriginalTextForLongString() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 500; i++) {
            sb.append((char) ('a' + (i % 26)));
        }
        String text = sb.toString();

        String preview = LogEvents.safePreview(text);

        assertTrue("preview should be much shorter than the original text",
                preview.length() < text.length());
        assertFalse("preview must not contain the original text as a substring",
                preview.contains(text));
        assertNotEquals(text, preview);
    }

    @Test
    public void safePreviewIsDeterministic() {
        String text = "some sensitive email body text with account details";

        String preview1 = LogEvents.safePreview(text);
        String preview2 = LogEvents.safePreview(text);

        assertEquals(preview1, preview2);
    }

    @Test
    public void safePreviewDiffersForDifferentInputs() {
        String preview1 = LogEvents.safePreview("hello world one");
        String preview2 = LogEvents.safePreview("hello world two");

        assertNotEquals(preview1, preview2);
    }

    @Test
    public void safePreviewContainsLengthAndHashPrefix() {
        String preview = LogEvents.safePreview("abc");

        assertTrue(preview.startsWith("len=3 sha256="));
    }

    @Test
    public void eventKeyConstantsAreDefined() {
        assertEquals("agent_mail_seen", LogEvents.AGENT_MAIL_SEEN);
        assertEquals("agent_tool_call", LogEvents.AGENT_TOOL_CALL);
        assertEquals("agent_reply_sent", LogEvents.AGENT_REPLY_SENT);
        assertEquals("llm_failed", LogEvents.LLM_FAILED);
        assertEquals("mail_channel_error", LogEvents.MAIL_CHANNEL_ERROR);
        assertEquals("agent_maxsteps_exceeded", LogEvents.AGENT_MAXSTEPS_EXCEEDED);
    }
}
